import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { createModel } from '../site/js/model.js';
const game=JSON.parse(await readFile(new URL('../site/data/bills-chiefs.json',import.meta.url),'utf8'));
const model=createModel(game);
// Independent checkpoints transcribed from the official gamebook, not generated by the normalizer.
const finals={BUF:[36,109,329,313,22,0,0,444],KC:[42,182,378,370,86,0,0,638]};
for(const team of ['BUF','KC']) assert.deepEqual(Object.values(model.totals[team]),finals[team]);
const quarterYards=[[[34,49,49],[63,11,11]],[[74,113,102],[92,114,107]],[[76,195,184],[166,183,175]],[[109,329,313],[176,309,301]],[[109,329,313],[182,378,370]]];
for(const [i,q] of model.quarters.entries()) for(const [j,t] of ['BUF','KC'].entries()) assert.deepEqual([q.totals[t].rushing,q.totals[t].passing,q.totals[t].netPassing],quarterYards[i][j]);
const scores=[[6,0],[7,0],[7,6],[7,7],[7,13],[7,14],[13,14],[14,14],[14,17],[14,23],[20,23],[21,23],[21,26],[27,26],[29,26],[29,32],[29,33],[35,33],[36,33],[36,36],[36,42]];
assert.deepEqual(model.snapshots.filter(s=>s.before.BUF.score!==s.after.BUF.score||s.before.KC.score!==s.after.KC.score).map(s=>[s.after.BUF.score,s.after.KC.score]),scores);
for(const [t,count,attempts,conversions] of [['BUF',8,4,4],['KC',5,1,1]]) assert.deepEqual([model.fourthDowns[t].count,model.fourthDowns[t].attempts,model.fourthDowns[t].conversions],[count,attempts,conversions]);
assert.deepEqual(game.events.filter(e=>e.segments.some(s=>s.category==='PR')).map(e=>e.segments.find(s=>s.category==='PR').yards),[15,45]);
assert.equal(game.events.find(e=>e.id==='3032').nullified,true);
assert.equal(game.events.find(e=>e.id==='3032').segments.length,0);
assert.equal(game.events.at(-1).description,'END GAME');
assert.equal(game.events.at(-2).scoreAfter.KC,42);
assert.equal(model.quarters[3].totals.KC.score,36);
assert.ok(game.opening.includes('defers'));
console.log('Verified 189 source-order events, all 21 scoring changes, five period totals, returns and fourth-down decisions against official checkpoints.');
